"use client";

import { BillingControls } from "@/components/billing-controls";
import { DateTime } from "@/components/date-time";
import {
  useWorkspaceEntitlements,
  useWorkspaceQuota,
} from "@/components/workspace-quota";
import type { ClientBillingStatus } from "@/lib/billing/status";
import { AllowanceCard } from "./AllowanceCard";
import { HowSendingWorks } from "./HowSendingWorks";
import { PlanCard } from "./PlanCard";
import styles from "./usage.module.css";

export function UsageContent({
  initialBilling,
  advertisedPrice,
}: {
  initialBilling: ClientBillingStatus;
  advertisedPrice: { symbol: string; amount: number };
}) {
  const quota = useWorkspaceQuota();
  const access = useWorkspaceEntitlements();
  const gated = quota.mode === "gated";
  return (
    <div
      className={`${styles.usage} text-[var(--usage-text)] [font-family:var(--font-plus-jakarta),_system-ui,_sans-serif] leading-[1.55]`}
    >
      <header
        className={`workspace-screen-heading usage-heading [margin:20px_0_28px]`}
      >
        <p className="[font:500_11.5px_var(--font-jetbrains),monospace] tracking-[0.14em] uppercase text-[var(--usage-accent)] workspace-mono:text-[var(--usage-coral)] workspace-mono:tracking-[0.2em]">
          Your workspace
        </p>
        <h1 className="mt-2 text-[clamp(30px,4.6vw,46px)] font-extrabold leading-[1.08] tracking-[-0.04em] workspace-mono:font-bold workspace-mono:tracking-[-0.03em]">
          Usage
        </h1>
        <div className="mt-2 text-[var(--usage-muted)]">
          Your plan, subscription, and sending allowances.
        </div>
      </header>
      <BillingControls
        initialBilling={initialBilling}
        advertisedPrice={advertisedPrice}
        renderContent={(controls) => (
          <>
            <PlanCard controls={controls} />
            <section
              id="allowances"
              aria-labelledby="allowances-heading"
              className={
                gated
                  ? `usage-allowances grid grid-cols-[repeat(2,_minmax(0,_1fr))] gap-5 mt-6 [@media(max-width:_820px)]:grid-cols-1`
                  : "mt-6"
              }
            >
              <h2 id="allowances-heading" className="sr-only">
                Sending allowances
              </h2>
              {gated ? (
                <>
                  {(["Daily", "Monthly"] as const).map((label) => {
                    const value =
                      label === "Daily" ? quota.daily : quota.monthly;
                    const premiumMonthly =
                      label === "Monthly" && quota.plan === "PAID";
                    const periodDescription =
                      label === "Daily"
                        ? "per UTC day"
                        : premiumMonthly
                          ? "this billing period"
                          : "this monthly period";
                    return (
                      <AllowanceCard
                        key={label}
                        title={`${label} allowance`}
                        remaining={value.remaining}
                        total={value.limit}
                        sent={value.sent}
                        queued={value.reserved}
                        used={value.used}
                        unitText={`${value.limit} emails ${periodDescription}`}
                        resetsAt={value.resetsAt}
                        resetUtcText={
                          value.resetsAt ? (
                            <>
                              Resets{" "}
                              <time dateTime={value.resetsAt}>
                                {new Intl.DateTimeFormat("en-US", {
                                  timeZone: "UTC",
                                  month: "short",
                                  day: "numeric",
                                  year: "numeric",
                                  hour: "2-digit",
                                  minute: "2-digit",
                                  hourCycle: "h23",
                                }).format(new Date(value.resetsAt))}{" "}
                                UTC
                              </time>
                            </>
                          ) : undefined
                        }
                        resetLocalText={
                          value.resetsAt ? (
                            <>
                              <DateTime value={value.resetsAt} /> (your local
                              time)
                            </>
                          ) : undefined
                        }
                        unavailable={value.startsAt === null}
                        followsBillingPeriod={premiumMonthly}
                        period={label === "Daily" ? "daily" : "monthly"}
                      />
                    );
                  })}
                </>
              ) : (
                <AllowanceCard
                  title="Rolling 24-hour allowance"
                  remaining={Math.max(0, quota.limit - quota.used)}
                  total={quota.limit}
                  sent={quota.used}
                  queued={0}
                  used={quota.used}
                  unitText={`${quota.limit} emails per rolling 24 hours`}
                  period="rolling"
                />
              )}
            </section>
            {gated && (
              <p className="usage-explainer mt-5.5 max-w-[46em] text-[var(--usage-muted)] text-[14px]">
                Queued emails reserve both allowances. Sent means Gmail accepted
                an email, not confirmed recipient delivery. Daily allowances
                reset at midnight UTC. Free monthly allowances reset on the
                first day of each UTC calendar month; Premium monthly allowances
                follow the verified subscription billing period. Unused emails
                do not roll over.
              </p>
            )}
            <HowSendingWorks
              batchSize={access.limits.campaignRecipients}
              gated={gated}
            />
          </>
        )}
      />
    </div>
  );
}
